/* Chinese Econ JMC — placement statistics page. Data comes from data.js (generated by scripts/build.py).
   Every chart title states its finding and is computed from the current selection. */
(function () {
  "use strict";

  const D = window.JMC_DATA;
  const $ = (id) => document.getElementById(id);
  if (!D) { $("lede").textContent = "data.js 未找到，请先运行 python scripts/build.py"; return; }
  $("generated").textContent = D.generated;

  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const pct = (k, n) => (n ? Math.round(100 * k / n) : 0);
  const count = (list, f) => list.filter(f).length;

  // placement categories, in stacking order; colors live in stats.css (.k-<key>)
  const TYPES = [
    { key: "fac", label: "教职", test: (c) => c.placement_type === "Faculty" },
    { key: "pd", label: "博后", test: (c) => c.placement_type === "Postdoc" },
    { key: "ind", label: "业界及其他", test: (c) => c.placement_type === "Industry & Other" },
    { key: "def", label: "延期", test: (c) => c.placement_type === "Deferred" },
    { key: "unk", label: "未知", test: (c) => !c.placement },
  ];
  const isFac = (c) => c.placement_type === "Faculty";
  const isFinal = (c) => ["Faculty", "Postdoc", "Industry & Other"].includes(c.placement_type);
  const facRate = (list) => { const k = list.filter(isFinal); return { fac: count(k, isFac), n: k.length, p: pct(count(k, isFac), k.length) }; };
  const HOME = ["中国大陆", "港澳"];
  const undergrad = (c) => {
    const e = (c.education || []).find((x) => /学士/.test(x.degree));
    if (!e) return null;
    return e.school.replace(/^（中国）|（中国）$/g, "").replace("对外经贸大学", "对外经济贸易大学").trim();
  };
  // PhD program: the school section, or the PhD school in the bio when the section is not a school
  // (e.g. 2024-2025 "中国经济学年会“学术之星”", which has no Chinese school name)
  const phdSchool = (c) => {
    if (c.school_zh) return c.school_zh;
    const e = (c.education || []).find((x) => /博士/.test(x.degree));
    return e ? e.school : c.school;
  };
  const isPkuThu = (c) => /^(北京大学|清华大学)/.test(undergrad(c) || "");

  // cycles with at least one placement, newest first
  const placedCycles = D.cycles.filter((cy) => D.candidates.some((c) => c.cycle === cy && c.placement));

  // ------------------------------------------------------------ tooltip ----
  const tip = $("tip");
  document.addEventListener("mouseover", (e) => {
    const t = e.target.closest("[data-tip]");
    if (!t) { tip.hidden = true; return; }
    tip.innerHTML = t.dataset.tip;
    tip.hidden = false;
  });
  document.addEventListener("mousemove", (e) => {
    if (tip.hidden) return;
    const pad = 14, w = tip.offsetWidth, h = tip.offsetHeight;
    let x = e.clientX + pad, y = e.clientY + pad;
    if (x + w > window.innerWidth - 8) x = e.clientX - w - pad;
    if (y + h > window.innerHeight - 8) y = e.clientY - h - pad;
    tip.style.transform = `translate(${x}px, ${y}px)`;
  });
  document.addEventListener("mouseleave", () => { tip.hidden = true; });

  const empty = (msg) => `<p class="empty-note">${msg}</p>`;

  // horizontal bar list; rows = [{label, sub?, v, text, tip, cls?} | {group}]; optional dashed reference line at `ref`
  function barList(rows, { max, ref, refLabel, wide, color = "fac" } = {}) {
    const m = max || Math.max(...rows.filter((r) => !r.group).map((r) => r.v), 1);
    const refX = ref != null ? (100 * ref / m).toFixed(1) : null;
    const body = rows.map((r) => r.group
      ? `<div class="b-group">${esc(r.group)}</div>`
      : `<div class="b-row ${r.cls || ""}" data-tip="${r.tip}">
          <span class="b-label">${esc(r.label)}${r.sub ? `<em>${esc(r.sub)}</em>` : ""}</span>
          <span class="b-track">${refX != null ? `<i class="ref" style="left:${refX}%"></i>` : ""}<span class="fill k-${color}" style="width:${(100 * r.v / m).toFixed(1)}%"></span></span>
          <span class="b-val">${r.text}</span>
        </div>`).join("");
    const key = refX != null
      ? `<div class="b-row ref-key"><span></span><span class="b-track"><span class="ref-label" style="left:${refX}%">${refLabel}</span></span><span></span></div>`
      : "";
    return `<div class="bars ${wide ? "wide" : ""}">${body}${key}</div>`;
  }

  // ---------------------------------------------------- cycle selection ----
  const SEG = [{ v: "all", label: "全部年度" }, ...D.cycles.map((cy) => ({ v: cy, label: cy }))];
  let sel = "all";
  try { const s = localStorage.getItem("jmc-stats-cycle"); if (SEG.some((o) => o.v === s)) sel = s; } catch (e) { /* storage unavailable */ }
  // "all" = every cycle that already has placement information
  const selected = () => D.candidates.filter((c) => (sel === "all" ? placedCycles.includes(c.cycle) : c.cycle === sel));
  const selLabel = () => (sel === "all" ? placedCycles.slice().reverse().join(" 与 ") : sel);

  $("cycle-seg").addEventListener("click", (e) => {
    const b = e.target.closest("button[data-v]");
    if (!b) return;
    sel = b.dataset.v;
    try { localStorage.setItem("jmc-stats-cycle", sel); } catch (err) { /* ignore */ }
    render();
  });

  // ------------------------------------------------------- hero facts ----
  function renderHero(list) {
    const r = facRate(list);
    if (!r.n) { $("hero").innerHTML = empty(`${esc(selLabel())} 还没有去向信息（仍在求职中）。下面的本科来源与博士项目仍可参考。`); return; }
    const fac = list.filter(isFac);
    const home = count(fac, (c) => HOME.includes(c.placement_region)), us = count(fac, (c) => c.placement_region === "美国");
    const insts = topInsts(fac).slice(0, 3);
    const top3 = insts.reduce((s, [, n]) => s + n, 0);
    $("hero").innerHTML = `
      <div class="fact"><div class="big">${r.p}%</div><div class="what">已有最终去向的人拿到教职</div><div class="how">${r.fac} / ${r.n} 人</div></div>
      <div class="fact"><div class="big">${pct(home, fac.length)}%</div><div class="what">的教职在中国大陆与港澳</div><div class="how">美国 ${pct(us, fac.length)}% · 其他海外 ${pct(fac.length - home - us, fac.length)}%</div></div>
      <div class="fact"><div class="big">${pct(top3, fac.length)}%</div><div class="what">的教职去了${insts.map(([k]) => esc(k)).join("、")}</div><div class="how">${top3} / ${fac.length} 人</div></div>`;
  }

  // ------------------------------------- 1. placement mix by cycle (all) ----
  function renderMix() {
    const rows = placedCycles.map((cy) => {
      const list = D.candidates.filter((c) => c.cycle === cy);
      return { cy, n: list.length, parts: TYPES.map((t) => ({ ...t, k: count(list, t.test) })), r: facRate(list) };
    });
    const [last, prev] = rows;
    $("mix-title").textContent = last
      ? `${last.cy} 已知去向中 ${last.r.p}% 为教职` + (prev ? `，${prev.cy} 为 ${prev.r.p}%` : "")
      : "历年去向构成";
    $("mix").innerHTML = `<div class="legend">${TYPES.map((t) => `<span><i class="sw k-${t.key}"></i>${t.label}</span>`).join("")}</div>` +
      rows.map((r) => `
      <div class="mix-row">
        <div class="mix-label"><b>${r.cy}</b><span>${r.n} 人</span></div>
        <div class="stack">${r.parts.filter((p) => p.k).map((p) => {
          const s = pct(p.k, r.n);
          return `<span class="k-${p.key}" style="flex-grow:${p.k}" data-tip="<b>${r.cy}</b><br>${p.label}：${p.k} 人（${s}%）">${s >= 8 ? `<b>${p.label} ${s}%</b>` : ""}</span>`;
        }).join("")}</div>
      </div>`).join("");
  }

  // ------------------------- 2. faculty regions: dumbbell across cycles ----
  function renderRegions() {
    const cys = placedCycles.slice().reverse(); // oldest -> newest
    const facBy = cys.map((cy) => D.candidates.filter((c) => c.cycle === cy && isFac(c)));
    const regionOf = (c) => c.placement_region || "未归类";
    const share = (i, r) => (facBy[i].length ? count(facBy[i], (c) => regionOf(c) === r) / facBy[i].length : 0);
    const regions = [...new Set(facBy.flat().map(regionOf))];
    if (!regions.length) { $("regions-title").textContent = "教职去向地区"; $("regions").innerHTML = empty("暂无教职数据。"); return; }
    const L = cys.length - 1;
    regions.sort((a, b) => share(L, b) - share(L, a) || share(0, b) - share(0, a));
    const max = Math.min(1, Math.ceil(Math.max(...regions.flatMap((r) => cys.map((_, i) => share(i, r)))) * 10) / 10);
    const x = (v) => (100 * v / max).toFixed(1);
    // title: largest destination, plus the biggest mover if it moved >= 5 points
    const top = regions[0];
    let mover = null;
    if (L > 0) {
      for (const r of regions) {
        const d = share(L, r) - share(L - 1, r);
        if (r !== top && (!mover || Math.abs(d) > Math.abs(mover.d))) mover = { r, d };
      }
    }
    $("regions-title").textContent = `${top}占 ${Math.round(100 * share(L, top))}% 的教职` +
      (mover && Math.abs(mover.d) >= 0.05 ? `；${mover.r}从 ${Math.round(100 * share(L - 1, mover.r))}% ${mover.d > 0 ? "升" : "降"}到 ${Math.round(100 * share(L, mover.r))}%` : "");
    const step = max > 0.5 ? 0.25 : 0.1;
    const ticks = []; for (let t = 0; t <= max + 1e-9; t += step) ticks.push(t);
    const legend = `<div class="legend">${cys.map((cy, i) => `<span><i class="dot ${i === L ? "now" : "then"}"></i>${cy}（${facBy[i].length} 人）</span>`).join("")}</div>`;
    const rows = regions.map((r) => {
      const vals = cys.map((_, i) => share(i, r));
      const lo = Math.min(...vals), hi = Math.max(...vals);
      const tipTxt = `<b>${esc(r)}</b><br>` + cys.map((cy, i) => `${cy}：${count(facBy[i], (c) => regionOf(c) === r)} 人（${Math.round(100 * vals[i])}%）`).join("<br>");
      return `<div class="db-row" data-tip="${tipTxt}">
        <span class="b-label">${esc(r)}</span>
        <span class="db-track">${ticks.map((t) => `<i class="grid" style="left:${x(t)}%"></i>`).join("")}<i class="span" style="left:${x(lo)}%;width:${(x(hi) - x(lo)).toFixed(1)}%"></i>${vals.map((v, i) => `<i class="dot ${i === L ? "now" : "then"}" style="left:${x(v)}%"></i>`).join("")}</span>
        <span class="b-val">${Math.round(100 * vals[L])}%</span>
      </div>`;
    }).join("");
    const axis = `<div class="db-row axis"><span></span><span class="db-track">${ticks.map((t) => `<span class="tick" style="left:${x(t)}%">${Math.round(100 * t)}%</span>`).join("")}</span><span></span></div>`;
    $("regions").innerHTML = legend + rows + axis;
  }

  // ------------------------------------------- 3. who gets faculty jobs ----
  const TIERS = [
    { label: "美国 #1–10", test: (c) => c.region === "美国区域" && c.rank && c.rank <= 10 },
    { label: "美国 #11–20", test: (c) => c.region === "美国区域" && c.rank > 10 && c.rank <= 20 },
    { label: "美国 #21–40", test: (c) => c.region === "美国区域" && c.rank > 20 && c.rank <= 40 },
    { label: "美国 #41+", test: (c) => c.region === "美国区域" && (c.rank > 40 || !c.rank) },
    { label: "加拿大院校", test: (c) => c.region !== "美国区域" },
  ];
  function renderWho(list) {
    const all = facRate(list);
    if (!all.n) { $("who-title").textContent = "谁更容易拿到教职"; $("who").innerHTML = empty("暂无去向数据。"); return; }
    const row = (label, sub) => {
      const r = facRate(sub);
      const us = count(sub, (c) => isFac(c) && c.placement_region === "美国");
      return r.n ? { label, v: r.p, text: `${r.p}%<em>n=${r.n}</em>`, cls: r.n < 15 ? "thin" : "",
        tip: `<b>${esc(label)}</b><br>教职 ${r.fac} / ${r.n} 人（${r.p}%）<br>其中美国教职 ${us} 人` } : null;
    };
    const pku = facRate(list.filter(isPkuThu)), other = facRate(list.filter((c) => !isPkuThu(c)));
    const rows = [
      { group: "本科院校" }, row("北大 / 清华", list.filter(isPkuThu)), row("其他", list.filter((c) => !isPkuThu(c))),
      { group: "博士院校" }, ...TIERS.map((t) => row(t.label, list.filter(t.test))),
    ].filter(Boolean);
    $("who-title").textContent = pku.n >= 10 && pku.p > other.p
      ? `本科北大/清华的人教职率 ${pku.p}%，其他人 ${other.p}%`
      : `全体教职率 ${all.p}%`;
    $("who").innerHTML = barList(rows, { max: 100, ref: all.p, refLabel: `平均 ${all.p}%` }) +
      `<p class="note small">浅色条表示该组少于 15 人，波动较大。</p>`;
  }

  // ------------------------------------------- 4. faculty rate by field ----
  function renderFields(list) {
    const all = facRate(list);
    const rows = (D.field_categories || []).filter((f) => f !== "Other").map((f) => {
      const r = facRate(list.filter((c) => (c.fields || []).includes(f)));
      return { label: f, v: r.p, n: r.n, text: `${r.p}%<em>n=${r.n}</em>`, tip: `<b>${esc(f)}</b><br>教职 ${r.fac} / ${r.n} 人（${r.p}%）` };
    }).filter((r) => r.n >= 10).sort((a, b) => b.v - a.v || b.n - a.n);
    if (!rows.length) { $("fields-title").textContent = "各研究领域的教职率"; $("fields").innerHTML = empty("样本不足。"); return; }
    $("fields-title").textContent = `${rows.slice(0, 3).map((r) => r.label).join("、")} 方向教职率最高`;
    $("fields").innerHTML = barList(rows, { max: 100, ref: all.p, refLabel: `平均 ${all.p}%`, wide: true });
  }

  // ------------------------------------------- 5. top hiring institutions ----
  function topInsts(fac) {
    const m = new Map();
    for (const c of fac) { const k = c.placement_inst || "其他（未归类）"; m.set(k, (m.get(k) || 0) + 1); }
    return [...m].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], "zh"));
  }
  function renderInsts(list) {
    const fac = list.filter(isFac);
    const all = topInsts(fac);
    const top = all.filter(([, n]) => n >= 2).slice(0, 12);
    if (!top.length) { $("insts-title").textContent = "主要教职去向机构"; $("insts").innerHTML = empty("暂无录用 2 人及以上的机构。"); return; }
    const region = (name) => (fac.find((c) => c.placement_inst === name) || {}).placement_region || "";
    const t3 = top.slice(0, 3), t3n = t3.reduce((s, [, n]) => s + n, 0);
    $("insts-title").textContent = `${t3.map(([k]) => k).join("、")} 合计招了 ${pct(t3n, fac.length)}% 的教职`;
    const rest = all.length - top.length, restN = fac.length - top.reduce((s, [, n]) => s + n, 0);
    $("insts").innerHTML = barList(top.map(([k, n]) => ({ label: k, sub: region(k), v: n, text: `${n}`,
      tip: `<b>${esc(k)}</b>（${esc(region(k))}）<br>${n} 人，占教职 ${pct(n, fac.length)}%` })), { wide: true }) +
      (rest ? `<p class="note small">另有 ${rest} 家机构共 ${restN} 人。</p>` : "");
  }

  // ------------------------------------- 6. industry: sectors and employers ----
  const SECTOR_OTHER = "其他";
  function renderIndustry(list) {
    const ind = list.filter((c) => c.placement_type === "Industry & Other");
    if (!ind.length) { $("ind-title").textContent = "业界去向"; $("ind").innerHTML = empty("暂无业界去向数据。"); return; }
    const tally = (key) => {
      const m = new Map();
      for (const c of ind) { const k = key(c); if (k) m.set(k, (m.get(k) || 0) + 1); }
      return [...m].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], "zh"));
    };
    const sectors = tally((c) => c.placement_sector || SECTOR_OTHER);
    sectors.sort((a, b) => (a[0] === SECTOR_OTHER) - (b[0] === SECTOR_OTHER) || b[1] - a[1]); // 其他 last
    const sectorOf = new Map(ind.map((c) => [c.placement_employer, c.placement_sector]));
    const employers = tally((c) => c.placement_employer).filter(([k, n]) => n >= 2 && !k.startsWith("其他"));
    const [top] = sectors;
    $("ind-title").textContent = `业界去向中 ${pct(top[1], ind.length)}% 是${top[0]}`;
    const sectorRows = sectors.map(([k, n]) => ({ label: k, v: n, text: `${pct(n, ind.length)}%<em>${n} 人</em>`,
      tip: `<b>${esc(k)}</b><br>${n} / ${ind.length} 人（${pct(n, ind.length)}%）` }));
    const empRows = employers.slice(0, 10).map(([k, n]) => ({ label: k, sub: sectorOf.get(k) || "", v: n, text: `${n}`,
      tip: `<b>${esc(k)}</b>（${esc(sectorOf.get(k) || "")}）<br>${n} 人，占业界去向 ${pct(n, ind.length)}%` }));
    $("ind").innerHTML = `
      <div class="sub-col"><h3>按类别</h3>${barList(sectorRows, { color: "ind" })}</div>
      <div class="sub-col"><h3>主要雇主（2 人及以上）</h3>${empRows.length ? barList(empRows, { color: "ind", wide: true }) : empty("暂无。")}</div>`;
  }

  // --------------------------------------- 7 & 8. undergrad / PhD origin ----
  function originChart(list, keyFn, titleId, boxId, titleFn) {
    const m = new Map();
    for (const c of list) { const k = keyFn(c); if (k) m.set(k, (m.get(k) || 0) + 1); }
    const top = [...m].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], "zh")).slice(0, 12);
    const known = [...m.values()].reduce((s, n) => s + n, 0);
    if (!top.length) { $(titleId).textContent = titleFn(null); $(boxId).innerHTML = empty("暂无数据。"); return; }
    $(titleId).textContent = titleFn(top, known);
    $(boxId).innerHTML = barList(top.map(([k, n]) => ({ label: k, v: n, text: `${n}`, tip: `<b>${esc(k)}</b><br>${n} 人，占 ${pct(n, known)}%` })), { wide: true, color: "neu" });
  }

  function render() {
    $("cycle-seg").innerHTML = SEG.map((o) =>
      `<button type="button" role="tab" aria-selected="${o.v === sel}" data-v="${o.v}" class="${o.v === sel ? "active" : ""}">${o.label}</button>`).join("");
    const list = selected();
    $("lede").innerHTML = `<b>${esc(selLabel())}</b> · ${list.length} 位候选人`;
    renderHero(list);
    renderWho(list);
    renderFields(list);
    renderInsts(list);
    renderIndustry(list);
    originChart(list, undergrad, "ug-title", "ug", (top, n) => top
      ? `本科最多来自${top.slice(0, 3).map(([k]) => k).join("、")}（合计 ${pct(top.slice(0, 3).reduce((s, [, k]) => s + k, 0), n)}%）`
      : "本科来源");
    originChart(list, phdSchool, "phd-title", "phd", (top) => top
      ? `${top.slice(0, 3).map(([k]) => k).join("、")} 的中国候选人最多`
      : "博士项目");
  }

  renderMix();
  renderRegions();
  render();
})();
